// 1E-d core: exchange this pod's federated SA token for an Azure OpenAI access token.
//
// The Azure Workload Identity webhook (enabled on AKS in 1B and bound via the
// n8n SA in 1E-a) projects a short-lived federated token at:
//   /var/run/secrets/azure/tokens/azure-identity-token
// and sets AZURE_CLIENT_ID / AZURE_TENANT_ID / AZURE_FEDERATED_TOKEN_FILE.
//
// We use the `client_credentials` grant with the federated token as a
// `client_assertion` (OAuth 2.0 client-assertion-type: jwt-bearer). That gives
// us an access token for the AOAI resource without ANY secret on disk.

const fs = require('fs');
const path = require('path');

const tokenFile = process.env.AZURE_FEDERATED_TOKEN_FILE
  || '/var/run/secrets/azure/tokens/azure-identity-token';
const tenantId = process.env.AZURE_TENANT_ID;
const clientId = process.env.AZURE_CLIENT_ID;

if (!tenantId || !clientId) {
  throw new Error(`Missing AZURE_TENANT_ID/AZURE_CLIENT_ID. WL identity webhook not active on this pod?`);
}

const federatedAssertion = fs.readFileSync(tokenFile, 'utf8').trim();

const params = new URLSearchParams({
  client_id: clientId,
  grant_type: 'client_credentials',
  client_assertion_type: 'urn:ietf:params:oauth:client-assertion-type:jwt-bearer',
  client_assertion: federatedAssertion,
  scope: 'https://cognitiveservices.azure.com/.default'
});

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: params.toString(),
  json: true
});

// Pull the caller's oid from the X-Auth-Request-User header (oauth2-proxy sets it
// for JWT-validated requests) so we can pass `user` to AOAI for Defender attribution.
const headers = $('Webhook').first().json.headers || {};
const callerOid = headers['x-auth-request-user'] || headers['x-forwarded-user'] || 'anonymous';

return [{
  json: {
    aoaiToken: resp.access_token,
    callerOid,
    userMessage: $('Webhook').first().json.body?.message || ''
  }
}];

